//! Canonical portable contracts for plugin administration, discovery and UI contributions.
//!
//! Descriptors are generated by Tembra from these declarations. Administrative proof values
//! identify a capability issued by the supervisor; constructing one does not grant authority.

mod administration;
mod browser_access;
mod capabilities;
mod manifest;
mod source;

pub use administration::*;
pub use browser_access::*;
pub use capabilities::*;
pub use manifest::*;
pub use source::*;

/// Registry containing checked source-provider methods, keyed by provider and operation.
pub const SOURCE_REGISTRY: &str = "swarmie.plugin-sources";

/// Registry containing lifecycle-owned browser contribution declarations.
pub const UI_REGISTRY: &str = "swarmie.ui-contributions";

/// Registry containing published runtime capabilities.
pub const CAPABILITY_REGISTRY: &str = "swarmie.capabilities";

/// Logical host of externally reachable runtime facades.
pub const RUNTIME_HOST: &str = "swarmie-runtime";

/// Exact Tembra revision accepted by this foundation.
pub const TEMBRA_REVISION: &str = "c394ec1f358a5054926f03409ac21f94d028617b";

/// Creates the source registry with deterministic conflict refusal.
pub fn source_registry() -> tembra::Result<tembra::core::Registry> {
    tembra::core::Registry::new(SOURCE_REGISTRY, tembra::core::ConflictPolicy::Error)
}

/// Creates the UI registry with deterministic conflict refusal.
pub fn ui_registry() -> tembra::Result<tembra::core::Registry> {
    tembra::core::Registry::new(UI_REGISTRY, tembra::core::ConflictPolicy::Error)
}
